"""Abstract syntax tree nodes shared by the parser and the engine.

Every node carries ``text``: the exact source text it was parsed from.  The
engine uses it to name output columns that have no alias (see SPEC.md).
"""


class Node:
    def __init__(self, text=""):
        self.text = text

    def __repr__(self):
        fields = ", ".join(
            "%s=%r" % (key, value)
            for key, value in self.__dict__.items()
            if key != "text"
        )
        return "%s(%s)" % (type(self).__name__, fields)


class Expr(Node):
    """Base class for expression nodes."""


class Literal(Expr):
    """A literal value: int, float, str, bool, or None."""

    def __init__(self, value, text=""):
        Node.__init__(self, text)
        self.value = value


class ColumnRef(Expr):
    """A reference to a column, with the name exactly as written (unquoted)."""

    def __init__(self, name, text=""):
        Node.__init__(self, text)
        self.name = name


class Star(Expr):
    """``*``; valid as a select item or as the sole argument of COUNT."""


class UnaryOp(Expr):
    """``op`` is ``"-"`` or ``"NOT"``."""

    def __init__(self, op, operand, text=""):
        Node.__init__(self, text)
        self.op = op.upper()
        self.operand = operand


class BinaryOp(Expr):
    """``op`` is one of OR, AND, =, !=, <>, <, <=, >, >=, +, -, *, /, ||."""

    def __init__(self, op, left, right, text=""):
        Node.__init__(self, text)
        self.op = op.upper()
        self.left = left
        self.right = right


class IsNull(Expr):
    def __init__(self, operand, negated=False, text=""):
        Node.__init__(self, text)
        self.operand = operand
        self.negated = negated


class InList(Expr):
    def __init__(self, operand, items, negated=False, text=""):
        Node.__init__(self, text)
        self.operand = operand
        self.items = list(items)
        self.negated = negated


class Between(Expr):
    def __init__(self, operand, low, high, negated=False, text=""):
        Node.__init__(self, text)
        self.operand = operand
        self.low = low
        self.high = high
        self.negated = negated


class Like(Expr):
    def __init__(self, operand, pattern, negated=False, text=""):
        Node.__init__(self, text)
        self.operand = operand
        self.pattern = pattern
        self.negated = negated


class FuncCall(Expr):
    """A scalar or aggregate function call; ``name`` is upper-cased."""

    def __init__(self, name, args, text=""):
        Node.__init__(self, text)
        self.name = name.upper()
        self.args = list(args)


class SelectItem(Node):
    def __init__(self, expr, alias=None, text=""):
        Node.__init__(self, text)
        self.expr = expr
        self.alias = alias


class OrderItem(Node):
    def __init__(self, expr, descending=False, text=""):
        Node.__init__(self, text)
        self.expr = expr
        self.descending = descending


class Select(Node):
    def __init__(
        self,
        items,
        table,
        distinct=False,
        where=None,
        group_by=(),
        having=None,
        order_by=(),
        limit=None,
        offset=None,
        text="",
    ):
        Node.__init__(self, text)
        self.items = list(items)
        self.table = table
        self.distinct = distinct
        self.where = where
        self.group_by = list(group_by)
        self.having = having
        self.order_by = list(order_by)
        self.limit = limit
        self.offset = offset


def child_exprs(node):
    """Return the direct child expressions of ``node`` (in source order)."""
    if isinstance(node, UnaryOp):
        return [node.operand]
    if isinstance(node, BinaryOp):
        return [node.left, node.right]
    if isinstance(node, IsNull):
        return [node.operand]
    if isinstance(node, InList):
        return [node.operand] + list(node.items)
    if isinstance(node, Between):
        return [node.operand, node.low, node.high]
    if isinstance(node, Like):
        return [node.operand, node.pattern]
    if isinstance(node, FuncCall):
        return list(node.args)
    return []


def walk(expr):
    """Yield ``expr`` and all of its descendants, depth first."""
    yield expr
    for child in child_exprs(expr):
        for node in walk(child):
            yield node


def _value_key(value):
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("int", value)
    if isinstance(value, float):
        return ("float", value)
    if isinstance(value, str):
        return ("str", value)
    return ("other", repr(value))


def expr_key(expr):
    """A hashable, text-independent key for structural expression equality.

    Column names are lower-cased, because column matching is case-insensitive.
    """
    if isinstance(expr, Literal):
        return ("lit", _value_key(expr.value))
    if isinstance(expr, ColumnRef):
        return ("col", expr.name.lower())
    if isinstance(expr, Star):
        return ("star",)
    if isinstance(expr, UnaryOp):
        return ("unary", expr.op, expr_key(expr.operand))
    if isinstance(expr, BinaryOp):
        return ("binary", expr.op, expr_key(expr.left), expr_key(expr.right))
    if isinstance(expr, IsNull):
        return ("isnull", expr.negated, expr_key(expr.operand))
    if isinstance(expr, InList):
        return ("in", expr.negated, expr_key(expr.operand),
                tuple(expr_key(item) for item in expr.items))
    if isinstance(expr, Between):
        return ("between", expr.negated, expr_key(expr.operand),
                expr_key(expr.low), expr_key(expr.high))
    if isinstance(expr, Like):
        return ("like", expr.negated, expr_key(expr.operand),
                expr_key(expr.pattern))
    if isinstance(expr, FuncCall):
        return ("func", expr.name, tuple(expr_key(arg) for arg in expr.args))
    return ("node", type(expr).__name__)

