"""Run SQL SELECT queries against CSV files. See SPEC.md."""

from .errors import QueryError
from . import engine


class Result:
    """The result of a query: ``columns`` names and ``rows`` of tuples."""

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = [tuple(row) for row in rows]

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other):
        if isinstance(other, Result):
            return self.columns == other.columns and self.rows == other.rows
        return NotImplemented


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    columns, rows = engine.execute(sql, directory)
    return Result(columns, rows)


__all__ = ["QueryError", "Result", "run"]

