def _check_grouped(expr, group_keys):
    # Aggregates are computed per group, and an expression that is itself a
    # GROUP BY expression (e.g. ``v + 1``) covers its columns too.
    if is_aggregate(expr):
        return
    if ast.expr_key(expr) in group_keys:
        return
    # Otherwise the spec constrains the columns: each one must be a GROUP BY
    # expression.  Recurse so that ``g = 'a'`` stays valid when grouping by g.
    if isinstance(expr, ast.ColumnRef):
        raise _grouped_error(expr)
    for child in ast.child_exprs(expr):
        _check_grouped(child, group_keys)

